solutionCode:
export function somarAte(n) {
  if (typeof n !== 'number' || n < 0) {
    throw new Error('n precisa ser um número maior ou igual a 0');
  }
  let soma = 0;
  for (let i = 1; i <= n; i++) {
    soma = soma + i;
  }
  return soma;
}
